<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/libs/kernel.inc.php';require_once dirname(__DIR__).'/libs/privacy-policy.inc.php';
$uid=alphano_require_login();if(!alphano_can('admin'))alphano_fail('Accesso riservato agli amministratori completi.',403);$fields=alphano_policy_fields();$error='';$values=alphano_managed_read('privacy-policy');
if($_SERVER['REQUEST_METHOD']==='POST'){
 alphano_require_csrf();try{$new=[];foreach($fields as $key=>[$label]){$v=$_POST[$key]??'';if(!is_string($v)||mb_strlen($v)>10000||str_contains($v,"\0"))throw new DomainException('Campo non valido: '.$label);$new[$key]=trim($v);}if($new['controller']===''||$new['email']===''||!filter_var($new['email'],FILTER_VALIDATE_EMAIL))throw new DomainException('Indica almeno titolare e un indirizzo email privacy valido.');$new['updated_at']=gmdate('c');alphano_managed_save('privacy-policy',$new,(string)($_POST['revision']??''));ConnectDB()->execute('INSERT INTO engine_admin_audit(actor,action,created_at) VALUES(?,?,?)',[$uid,'privacy-policy:update',time()]);header('Location: /admin/privacy.php?saved=1',true,303);exit;}catch(Throwable $e){$error=$e instanceof DomainException?$e->getMessage():'Salvataggio non riuscito.';$values=array_replace($values,array_filter(array_intersect_key($_POST,$fields),'is_string'));http_response_code(422);}
